import React, { useState } from 'react'
import { View, Text, TouchableOpacity, Dimensions, ActivityIndicator } from 'react-native'

import { useContexState } from '../../../hooks/context';
import { styles } from './styles';


export function Alert() {
    const { shoppingCartItem, setShoppingCartItem, selectedNumber, setSelectedNumber } = useContexState();


    return (selectedNumber !== null ? <>
        <TouchableOpacity onPress={() => {
            setSelectedNumber(null);
        }} style={{
            position: 'absolute',
            alignItems: 'center',
            justifyContent: 'center',
            minWidth: Dimensions.get('window').width,
            minHeight: Dimensions.get('window').height
        }} />


        <View style={styles.container} >
                    <Text style={{ color: '#fff', fontSize: 30, textAlign: 'center', marginHorizontal: 10 }}>Adicionando ao carrinho!</Text>
                    <ActivityIndicator size={37} color='#fff' style={{ marginTop: 10, marginBottom: 20 }} />

        </View>
    </> : null
    );
};
